      pos: ["autoriza\\w+ judicia\\w+ .{0,80}(acesso|extracao|quebra|afastamento|analise)", "(quebra|afastamento) (do|de) sigilo (de dados|telematico|dos dados|telefonico)", "deferi\\w* .{0,40}(acesso|extracao|quebra|afastamento)", "decisao (judicial )?(que )?.{0,40}(autorizou|deferiu) .{0,40}(acesso|extracao|quebra)", "termo de (consentimento|autorizacao) .{0,40}(acesso|aparelho)"],
      neg: ["(acessou|acessaram|visualizou|visualizaram|vasculhou|vasculharam|manuseou|manusearam|olhou|olharam|leu|leram) .{0,60}(whatsapp|conversas|mensagens|fotos|galeria|conteudo|arquivos)", "senha (foi )?(fornecida|franqueada|informada) (pelo|pela) (proprio|propria|conduzido|preso|suspeito|investigado|autuado)", "franque\\w+ (o )?acesso", "desbloque\\w+ .{0,30}(pelo|pela) (proprio|propria|conduzido|preso|suspeito)", "(no local|na abordagem|no momento da abordagem|durante a abordagem) .{0,80}(conversas|mensagens|whatsapp)"],
