      pos: ["cellebrite", "\\bufed\\b", "\\bxry\\b", "oxygen", "axiom", "magnet", "\\biped\\b", "avilla", "\\bftk\\b", "encase", "physical analyzer", "extracao (fisica|logica|full file system|do sistema de arquivos|forense)", "ferramenta forense"],
      neg: ["(captura|print)\\w* de tela .{0,80}(policia|agente|investigador|escrivao|delegad)", "(policia|agente|investigador|escrivao|delegad)\\w* .{0,80}(capturas? de tela|prints?|fotograf\\w+ (a|da) tela)", "fotograf\\w+ (a|da) tela", "extraid\\w+ manualmente", "(acesso|consulta) direta? (ao|do) aparelho"],
