      fund: "CPP, art. 158-A; ABNT NBR ISO/IEC 27037:2013",
      pos: ["\\bhash\\b", "sha-?(1|256|512)\\b", "\\bmd5\\b", "\\b[0-9a-f]{32}\\b", "\\b[0-9a-f]{40}\\b", "\\b[0-9a-f]{64}\\b"],
      neg: ["sem (o )?(calculo|registro|codigo) (do |de )?hash", "nao (foi|foram) (calculad|gerad|registrad)\\w* .{0,20}hash"],
